CREATE TABLE "Coupon" (id TEXT NOT NULL PRIMARY KEY,code TEXT NOT NULL UNIQUE,description TEXT NOT NULL DEFAULT '',active BOOLEAN NOT NULL DEFAULT true,type TEXT NOT NULL,value INTEGER NOT NULL,currency TEXT,recurring BOOLEAN NOT NULL DEFAULT false,"firstPurchaseOnly" BOOLEAN NOT NULL DEFAULT false,"startsAt" TIMESTAMP(3),"endsAt" TIMESTAMP(3),"maxUses" INTEGER,"perCustomerLimit" INTEGER NOT NULL DEFAULT 1,countries JSONB NOT NULL DEFAULT '[]');
CREATE TABLE "CouponProduct" ("couponId" TEXT NOT NULL REFERENCES "Coupon"(id) ON DELETE CASCADE,"productId" TEXT NOT NULL REFERENCES "Product"(id) ON DELETE CASCADE,PRIMARY KEY("couponId","productId"));
CREATE TABLE "CouponRedemption" (id TEXT NOT NULL PRIMARY KEY,"couponId" TEXT NOT NULL REFERENCES "Coupon"(id),"userId" TEXT NOT NULL REFERENCES "User"(id),"orderId" TEXT NOT NULL UNIQUE REFERENCES "Order"(id),state TEXT NOT NULL DEFAULT 'RESERVED',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "CouponRedemption_couponId_state_userId_idx" ON "CouponRedemption"("couponId",state,"userId");
